package com.kwl360.stickermaker;
import android.content.*;import android.graphics.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;
public class PackStore {
 static final String AUTH="com.kwl360.stickermaker.stickercontentprovider";
 static File dir(Context c,String id){File d=new File(c.getFilesDir(),"packs/"+id);d.mkdirs();return d;}
 static JSONArray packs(Context c){try{return new JSONArray(c.getSharedPreferences("packs",0).getString("data","[]"));}catch(Exception e){return new JSONArray();}}
 static void save(Context c,JSONArray a){c.getSharedPreferences("packs",0).edit().putString("data",a.toString()).apply();}
 static JSONObject get(Context c,String id){JSONArray a=packs(c);for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&id.equals(p.optString("id")))return p;}return null;}
 static String create(Context c,String name)throws Exception{String id="p"+System.currentTimeMillis();JSONObject p=new JSONObject();p.put("id",id);p.put("name",name);p.put("files",new JSONArray());JSONArray a=packs(c);a.put(p);save(c,a);return id;}
 static int count(Context c,String id){JSONObject p=get(c,id);return p==null?0:p.optJSONArray("files").length();}
 static void add(Context c,String id,Uri uri)throws Exception{JSONObject p=get(c,id);if(p==null)throw new Exception("الحزمة غير موجودة");JSONArray f=p.getJSONArray("files");if(f.length()>=30)throw new Exception("الحد الأقصى 30 ملصقًا في الحزمة");Bitmap src;try(InputStream in=c.getContentResolver().openInputStream(uri)){src=BitmapFactory.decodeStream(in);}if(src==null)throw new Exception("تعذر قراءة الصورة؛ استخدم PNG أو JPG أو WebP ثابت");Bitmap out=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(out);Paint paint=new Paint(3);float scale=Math.min(512f/src.getWidth(),512f/src.getHeight());float w=src.getWidth()*scale,h=src.getHeight()*scale;canvas.drawBitmap(src,null,new RectF((512-w)/2,(512-h)/2,(512+w)/2,(512+h)/2),paint);src.recycle();String filename=String.format(Locale.US,"sticker_%03d.webp",f.length()+1);File file=new File(dir(c,id),filename);int q=90;do{try(FileOutputStream fos=new FileOutputStream(file)){out.compress(Bitmap.CompressFormat.WEBP,q,fos);}q-=10;}while(file.length()>100*1024&&q>=20);out.recycle();if(file.length()>100*1024){file.delete();throw new Exception("الصورة تتجاوز حجم واتساب المسموح");}f.put(filename);if(f.length()==1){Bitmap tray=BitmapFactory.decodeFile(file.getAbsolutePath());Bitmap mini=Bitmap.createScaledBitmap(tray,96,96,true);try(FileOutputStream os=new FileOutputStream(new File(dir(c,id),"tray.png"))){mini.compress(Bitmap.CompressFormat.PNG,100,os);}tray.recycle();mini.recycle();}JSONArray all=packs(c);for(int i=0;i<all.length();i++){if(id.equals(all.optJSONObject(i).optString("id")))all.put(i,p);}save(c,all);}
 static void delete(Context c,String id){JSONArray a=packs(c),b=new JSONArray();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&!id.equals(p.optString("id")))b.put(p);}save(c,b);File d=dir(c,id);File[] fs=d.listFiles();if(fs!=null)for(File f:fs)f.delete();d.delete();}
}